#[cfg(test)]
mod tests {
    use rigorix_engine::capacity_ledger::domain::IdempotencyKey;
    use rigorix_engine::effect_commitment::application::{DispatchObservation, DispatchSeam};
    use rigorix_engine::effect_commitment::domain::EffectIntent;
    use uuid::Uuid;

    fn intent() -> EffectIntent {
        EffectIntent::new(
            Uuid::from_u128(1),
            Uuid::from_u128(2),
            1,
            IdempotencyKey::new("intent-key"),
            "payments.charge",
            "args-digest",
            "precondition-digest",
            "authority-digest",
        )
    }

    #[test]
    fn test_dispatchseam_is_defined() {
        // The seam is the component whose absence leaves the context compiled
        // and unreachable; it must be object-safe so the dispatch loop can hold
        // a boxed implementation.
        fn assert_object_safe(_: Option<Box<dyn DispatchSeam>>) {}
        assert_object_safe(None);
    }

    #[test]
    fn test_dispatchseam_interacts_with_effectcommitmentservice() {
        fn assert_send_sync<T: Send + Sync + ?Sized>() {}
        assert_send_sync::<dyn DispatchSeam>();
    }

    #[test]
    fn test_dispatchseam_interacts_with_intentkeyderivation() {
        // A lost response is an observation, not an absence: it maps to
        // Ambiguous and can never be collapsed into NotCommitted.
        let lost = DispatchObservation::Lost {
            reason: "response lost".to_string(),
        };
        assert_eq!(lost.clone(), lost);
        assert!(matches!(lost, DispatchObservation::Lost { .. }));
    }

    #[test]
    fn test_dispatchseam_interacts_with_effectintent() {
        // The seam takes ownership of the intent, so it must be an owned,
        // clonable value object.
        let intent = intent();
        let moved: EffectIntent = intent.clone();
        assert_eq!(moved, intent);
    }
}
